/**
 * schema.js — canonical column definitions for metrics.csv
 *
 * Derived from the ACTUAL output of `codesmell-ai --repo-path <dir>`.
 * Source: export_csv.py CSV_COLUMNS list + observed data types in metrics.csv.
 *
 * Do NOT edit this file to match a hypothetical schema.
 * If the Python pipeline changes, regenerate metrics.csv and update here.
 */

// ── Columns that MUST be present for the UI to function ─────────────────────
export const REQUIRED_COLUMNS = [
  'filename',
  'risk_score',
  'risk_category',
]

// ── All columns produced by codesmell-ai, with type hints ───────────────────
// type: 'str' | 'float' | 'int' | 'bool' | 'pydict' | 'str_enum'
export const COLUMN_SCHEMA = [
  // Identity
  { key: 'filename',                          type: 'str',      group: 'identity'      },

  // Graph / structural
  { key: 'degree',                            type: 'int',      group: 'graph'         },
  { key: 'in_degree',                         type: 'int',      group: 'graph'         },
  { key: 'pagerank',                          type: 'float',    group: 'graph'         },

  // Static analysis
  { key: 'cyclomatic_complexity',             type: 'int',      group: 'static'        },
  { key: 'loc',                               type: 'int',      group: 'static'        },
  { key: 'function_count',                    type: 'int',      group: 'static'        },
  { key: 'class_count',                       type: 'int',      group: 'static'        },
  { key: 'max_nesting_depth',                 type: 'int',      group: 'static'        },
  { key: 'smell_count_total',                 type: 'int',      group: 'static'        },
  { key: 'smell_breakdown',                   type: 'pydict',   group: 'static'        }, // Python dict string
  { key: 'maintainability_index',             type: 'float',    group: 'static'        },

  // Git history
  { key: 'commit_count',                      type: 'int',      group: 'git'           },
  { key: 'bug_fix_commit_count',              type: 'int',      group: 'git'           },
  { key: 'distinct_author_count',             type: 'int',      group: 'git'           },
  { key: 'days_since_last_modified',          type: 'int',      group: 'git'           },
  { key: 'has_insufficient_history',          type: 'bool',     group: 'git'           }, // "True"/"False"

  // Risk scoring
  { key: 'risk_score',                        type: 'float',    group: 'risk'          },
  { key: 'risk_category',                     type: 'str_enum', group: 'risk',
    values: ['Low Risk', 'Medium Risk', 'High Risk']                                   },

  // Weighted contributions (one per WEIGHTED_METRICS entry in risk_scorer.py)
  { key: 'pagerank_contribution',             type: 'float',    group: 'contribution'  },
  { key: 'cyclomatic_complexity_contribution',type: 'float',    group: 'contribution'  },
  { key: 'smell_count_total_contribution',    type: 'float',    group: 'contribution'  },
  { key: 'max_nesting_depth_contribution',    type: 'float',    group: 'contribution'  },
  { key: 'loc_contribution',                  type: 'float',    group: 'contribution'  },
  { key: 'structural_size_contribution',      type: 'float',    group: 'contribution'  },
  { key: 'bug_fix_commit_count_contribution', type: 'float',    group: 'contribution'  },
  { key: 'commit_count_contribution',         type: 'float',    group: 'contribution'  },
  { key: 'distinct_author_count_contribution',type: 'float',    group: 'contribution'  },

  // AI narrative
  { key: 'ai_explanation',                    type: 'str',      group: 'ai'            },
]

// ── Risk thresholds — MUST match risk_scorer.py constants exactly ────────────
export const RISK_THRESHOLDS = {
  LOW_MAX:    40,   // score < 40  → Low Risk
  MEDIUM_MAX: 70,   // score < 70  → Medium Risk
  // score ≥ 70 → High Risk
}

export const RISK_COLORS = {
  'Low Risk':    '#6EDC9B',
  'Medium Risk': '#F5C04F',
  'High Risk':   '#FF8374',
}

// ── Graph data availability note ────────────────────────────────────────────
// The metrics.csv contains per-file degree/in_degree/pagerank values but does
// NOT export the actual dependency edge list. Edges are computed at runtime
// in graph_builder.py (networkx DiGraph) and saved only as dependency_graph.png.
// The frontend graph view will display node metrics from the CSV but cannot
// reconstruct edges without a re-run or a separate edge export.
export const GRAPH_EDGES_AVAILABLE = false